return {
  userDefaults: userDefaults
};

function safeParse(val) {
  if (val === null || val === undefined) return null;
  if (typeof val === 'object') return val;
  if (typeof val === 'string') {
    try {
      const parsed = JSON.parse(val);
      return (typeof parsed === 'string') ? JSON.parse(parsed) : parsed;
    } catch (e) {
      return null;
    }
  }
  return null;
}

var pv_data = safeParse(input.pv_data);
if (!pv_data) return {};

var createRequisitionResponseDMData = {};
if (Array.isArray(pv_data)) {
  if (pv_data.length > 0) {
    createRequisitionResponseDMData =
      pv_data
        .map(elem1 => safeParse(elem1))
        .find(elem2 => elem2 && elem2.result && elem2.httpStatusCode) || {};
  }

  for (var i = 0; i < pv_data.length; i++) {
    var item = safeParse(pv_data[i]);
    if (item && Array.isArray(item.selectedItems)) {
      return {
        selectedItems: item.selectedItems,
        createRequisitionResponseDM:
          createRequisitionResponseDMData &&
          createRequisitionResponseDMData.result &&
          createRequisitionResponseDMData.result.data
            ? createRequisitionResponseDMData.result.data
            : {}
      };
    }
  }
}

return { selectedItems: [], createRequisitionResponseDM: {} };

